cat > /tmp/test_thresholds.js << 'EOF'
import { runEvaluations, generateReport } from '/private/tmp/100-tricks-runs/d64/with/h2-eval-thresholds/r5/packages/frai-core/src/eval/index.js';

const evaluations = runEvaluations({
  outputs: ['Hello', 'World'],
  references: ['hello', 'world']
});

console.log('Evaluations:');
evaluations.forEach((m) => {
  console.log(`  ${m.id}: ${m.score}`);
});

const reportWithThresholds = generateReport({
  evaluations,
  outputsPath: '/tmp/outputs.json',
  referencesPath: '/tmp/refs.json',
  thresholds: {
    exact_match: 0.9,
    toxicity: 0.95
  }
});

console.log('\nReport with thresholds:');
console.log(`  passed: ${reportWithThresholds.passed}`);
console.log('  thresholds:');
reportWithThresholds.thresholds.forEach((t) => {
  console.log(`    ${t.metric}: ${t.passed ? 'PASS' : 'FAIL'} (min: ${t.min}, score: ${t.score})`);
});
EOF
node /tmp/test_thresholds.js
